async function loadPassages(url) {
  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json();
}

const pools = passages.reduce((result, passage) => {
  const key = `${passage.category}:${passage.difficulty}`;
  if (!result[key]) {
    result[key] = [];
  }
  result[key].push(passage);
  return result;
}, {});

def chunk(values, size):
  if size <= 0:
    raise ValueError("size must be positive")
  result = []
  for index in range(0, len(values), size):
    result.append(values[index:index + size])
  return result

WITH ranked AS (
  SELECT id, category, difficulty,
    ROW_NUMBER() OVER (PARTITION BY category, difficulty ORDER BY RANDOM()) AS position
  FROM passages
)
SELECT id FROM ranked WHERE position <= 15;

