async def fetch_verified(client, passage_ids):
  results = {}
  for passage_id in passage_ids:
    for attempt in range(3):
      try:
        response = await client.get(f"/passages/{passage_id}")
        if response.status == 200:
          results[passage_id] = response.json()
          break
      except TimeoutError:
        if attempt == 2:
          raise
  return results

